fn frame(t: i32) {
    host::display::clear(0x0e0f13);
    if host::display::state_get(4) == 0 {
        host::display::state_set(4, 1);
        host::display::state_set(1, 50);
        let mut i: i32 = 0;
        while i < 16 {
            host::display::state_set(20 + i, 50);
            i = i + 1;
        }
    }
    let bal: i32 = host::display::state_get(1);
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    host::display::state_set(0, down);

    host::display::draw_string(60, 40, "PIGGY BANK", 0xffffff, 2);
    host::display::draw_number(60, 80, bal, 0x66ddff, 6);

    let head: i32 = host::display::state_get(3);
    let mut j: i32 = 0;
    while j < 16 {
        let v: i32 = host::display::state_get(20 + (head + j) % 16);
        let mut bh: i32 = v;
        if bh > 110 {
            bh = 110;
        }
        host::display::fill_rect(60 + j * 25, 280 - bh, 18, bh + 2, 0x3388cc);
        j = j + 1;
    }
    host::display::draw_string(60, 292, "LAST 16 BALANCES", 0x556677, 1);

    host::display::fill_rect(60, 330, 160, 70, 0x1a5c2a);
    host::display::draw_string(94, 352, "EARN +5", 0xccffdd, 2);
    host::display::fill_rect(292, 330, 160, 70, 0x5c1a1a);
    host::display::draw_string(316, 352, "SPEND -3", 0xffcccc, 2);

    let flash: i32 = host::display::state_get(2);
    if flash > 0 {
        host::display::draw_string(292, 420, "NOT ENOUGH SAVED", 0xbb3333, 1);
        host::display::state_set(2, flash - 1);
    }

    if down == 1 && prev == 0 {
        let px: i32 = host::display::pointer_x();
        let py: i32 = host::display::pointer_y();
        if py >= 330 && py < 400 {
            let mut newbal: i32 = -1;
            if px >= 60 && px < 220 {
                newbal = bal + 5;
            }
            if px >= 292 && px < 452 {
                if bal >= 3 {
                    newbal = bal - 3;
                } else {
                    host::display::state_set(2, 30);
                }
            }
            if newbal >= 0 {
                host::display::state_set(1, newbal);
                host::display::state_set(20 + head, newbal);
                host::display::state_set(3, (head + 1) % 16);
            }
        }
    }
    host::display::present();
}
